from common import task

# 1 (dev) soft delete through repository, service and API
task("mf-soft-delete", "multi-file",
     "Users must be soft-deleted: users.delete(id) marks a user deleted instead of removing it; every existing read "
     "(get, list_users, count, find_by_email) behaves as if deleted users do not exist; add restore(id) (undoes a "
     "delete; KeyError for unknown ids) and list_users(include_deleted=True). Creating a user with the email of a "
     "deleted user must still fail. Keep all current behaviour otherwise.",
     {"db.py": "ROWS = {}\nNEXT = [1]\n\ndef insert(row):\n    rid = NEXT[0]; NEXT[0] += 1\n    ROWS[rid] = dict(row, id=rid)\n    return rid\n\ndef remove(rid):\n    del ROWS[rid]\n",
      "users.py": "import db\n\ndef create(name, email):\n    if find_by_email(email):\n        raise ValueError('email taken')\n    return db.insert({'name': name, 'email': email.lower()})\n\ndef get(uid):\n    return db.ROWS[uid]\n\ndef find_by_email(email):\n    for r in db.ROWS.values():\n        if r['email'] == email.lower():\n            return r\n    return None\n\ndef list_users():\n    return sorted(db.ROWS.values(), key=lambda r: r['id'])\n\ndef count():\n    return len(db.ROWS)\n\ndef delete(uid):\n    db.remove(uid)\n",
      "api.py": "import users\n\ndef handle(method, path, body=None):\n    parts = path.strip('/').split('/')\n    try:\n        if method == 'GET' and parts == ['users']:\n            return 200, [u['name'] for u in users.list_users()]\n        if method == 'GET' and len(parts) == 2:\n            return 200, users.get(int(parts[1]))['name']\n        if method == 'DELETE' and len(parts) == 2:\n            users.delete(int(parts[1])); return 204, None\n        if method == 'POST' and parts == ['users']:\n            return 201, users.create(body['name'], body['email'])\n    except KeyError:\n        return 404, None\n    except ValueError as e:\n        return 409, str(e)\n    return 400, None\n"},
     {"hidden_t.py": "import users, api, db\na=users.create('A','a@x.io'); b=users.create('B','b@x.io')\nusers.delete(a)\nassert users.count()==1 and [u['name'] for u in users.list_users()]==['B']\nassert [u['name'] for u in users.list_users(include_deleted=True)]==['A','B']\nassert users.find_by_email('A@x.io') is None\ntry:\n    users.get(a); raise SystemExit('deleted user visible')\nexcept KeyError: pass\nassert api.handle('GET','/users/%d'%a)==(404,None) and api.handle('GET','/users')==(200,['B'])\nassert api.handle('POST','/users',{'name':'A2','email':'a@x.io'})[0]==409\nusers.restore(a); assert users.count()==2 and users.get(a)['name']=='A'\ntry:\n    users.restore(999); raise SystemExit('restore unknown')\nexcept KeyError: pass\nassert api.handle('DELETE','/users/%d'%b)==(204,None) and api.handle('GET','/users')==(200,['A'])\nassert len(db.ROWS)==2\nprint('ok')\n"},
     "python3 hidden_t.py",
     {"users.py": "import db\n\ndef _live():\n    return [r for r in db.ROWS.values() if not r.get('deleted')]\n\ndef create(name, email):\n    e = email.lower()\n    if any(r['email'] == e for r in db.ROWS.values()):\n        raise ValueError('email taken')\n    return db.insert({'name': name, 'email': e})\n\ndef get(uid):\n    r = db.ROWS[uid]\n    if r.get('deleted'):\n        raise KeyError(uid)\n    return r\n\ndef find_by_email(email):\n    for r in _live():\n        if r['email'] == email.lower():\n            return r\n    return None\n\ndef list_users(include_deleted=False):\n    rows = db.ROWS.values() if include_deleted else _live()\n    return sorted(rows, key=lambda r: r['id'])\n\ndef count():\n    return len(_live())\n\ndef delete(uid):\n    get(uid)\n    db.ROWS[uid]['deleted'] = True\n\ndef restore(uid):\n    db.ROWS[uid]['deleted'] = False\n"},
     split="dev")

# 2 config layering with typed env overrides
task("mf-config-layers", "multi-file",
     "Settings come from defaults.json. Add environment overrides: a variable APP_<KEY> overrides a top-level key and "
     "APP_<A>__<B> a nested key (case-insensitive). Values are converted to the type of the default they replace "
     "(int, float, bool from true/false/1/0/yes/no, list from comma-separated strings); a value that cannot be "
     "converted raises ConfigError naming the variable. Unknown keys raise ConfigError too. app.py must keep working.",
     {"defaults.json": "{\"port\": 8080, \"debug\": false, \"ratio\": 0.5, \"name\": \"svc\", \"hosts\": [\"a\"], \"db\": {\"pool\": 5, \"url\": \"sqlite://\"}}\n",
      "config.py": "import json, os\n\nclass ConfigError(Exception):\n    pass\n\ndef load(path=None, env=None):\n    path = path or os.path.join(os.path.dirname(os.path.abspath(__file__)), 'defaults.json')\n    with open(path) as f:\n        return json.load(f)\n",
      "app.py": "from config import load\n\ndef banner(env=None):\n    c = load(env=env)\n    return f\"{c['name']} on :{c['port']} pool={c['db']['pool']} debug={c['debug']}\"\n"},
     {"hidden_t.py": "from config import load, ConfigError\nfrom app import banner\nassert banner({})=='svc on :8080 pool=5 debug=False'\nc=load(env={'APP_PORT':'9000','app_debug':'yes','APP_RATIO':'0.25','APP_HOSTS':'x, y','APP_DB__POOL':'12','APP_DB__URL':'pg://h','PATH':'/bin'})\nassert c['port']==9000 and c['debug'] is True and c['ratio']==0.25 and c['hosts']==['x','y'] and c['db']=={'pool':12,'url':'pg://h'}, c\nassert load(env={'APP_DEBUG':'0'})['debug'] is False\nfor bad in ({'APP_PORT':'abc'},{'APP_DEBUG':'maybe'},{'APP_NOPE':'1'},{'APP_DB__X':'1'}):\n    try:\n        load(env=bad); raise SystemExit('accepted %r'%bad)\n    except ConfigError as e:\n        assert list(bad)[0].upper() in str(e).upper(), str(e)\nassert banner({'APP_PORT':'1'})=='svc on :1 pool=5 debug=False'\nimport os; os.environ['APP_NAME']='fromenv'; assert load()['name']=='fromenv'\nprint('ok')\n"},
     "python3 hidden_t.py",
     {"config.py": "import json, os\n\nclass ConfigError(Exception):\n    pass\n\ndef _conv(var, raw, default):\n    s = raw.strip()\n    try:\n        if isinstance(default, bool):\n            m = {'true': True, '1': True, 'yes': True, 'false': False, '0': False, 'no': False}\n            return m[s.lower()]\n        if isinstance(default, int):\n            return int(s)\n        if isinstance(default, float):\n            return float(s)\n        if isinstance(default, list):\n            return [x.strip() for x in s.split(',') if x.strip()]\n        return s\n    except (KeyError, ValueError):\n        raise ConfigError(f'{var}: cannot convert {raw!r}')\n\ndef load(path=None, env=None):\n    path = path or os.path.join(os.path.dirname(os.path.abspath(__file__)), 'defaults.json')\n    with open(path) as f:\n        c = json.load(f)\n    env = os.environ if env is None else env\n    for var, raw in env.items():\n        if not var.upper().startswith('APP_'):\n            continue\n        keys = var[4:].lower().split('__')\n        node = c\n        for k in keys[:-1]:\n            if not isinstance(node.get(k), dict):\n                raise ConfigError(f'{var}: unknown key')\n            node = node[k]\n        if keys[-1] not in node or isinstance(node[keys[-1]], dict):\n            raise ConfigError(f'{var}: unknown key')\n        node[keys[-1]] = _conv(var, raw, node[keys[-1]])\n    return c\n"})

# 3 atomic transfers with an audit trail
task("mf-atomic-transfer", "multi-file",
     "Add an audit trail to transfers: every successful transfer appends one entry {'from','to','amount','balance_from',"
     "'balance_to'} to ledger.AUDIT (balances after the transfer). A transfer that fails for any reason (unknown "
     "account, insufficient funds, non-positive amount, or an error raised by the notifier) must leave balances and "
     "the audit trail exactly as they were. Notifications must only be sent for transfers that succeed.",
     {"accounts.py": "BALANCES = {}\n\nclass Insufficient(Exception):\n    pass\n\ndef open_account(name, amount=0):\n    BALANCES[name] = amount\n\ndef debit(name, amount):\n    if BALANCES[name] < amount:\n        raise Insufficient(name)\n    BALANCES[name] -= amount\n\ndef credit(name, amount):\n    BALANCES[name] += amount\n",
      "ledger.py": "AUDIT = []\n",
      "notify.py": "SENT = []\nFAIL = [False]\n\ndef send(msg):\n    if FAIL[0]:\n        raise RuntimeError('mail down')\n    SENT.append(msg)\n",
      "transfer.py": "import accounts, notify\n\ndef transfer(src, dst, amount):\n    accounts.debit(src, amount)\n    notify.send(f'{src}->{dst}:{amount}')\n    accounts.credit(dst, amount)\n"},
     {"hidden_t.py": "import accounts, ledger, notify\nfrom transfer import transfer\naccounts.open_account('a',100); accounts.open_account('b',0)\ntransfer('a','b',30)\nassert accounts.BALANCES=={'a':70,'b':30} and ledger.AUDIT==[{'from':'a','to':'b','amount':30,'balance_from':70,'balance_to':30}] and notify.SENT==['a->b:30']\nsnap=(dict(accounts.BALANCES), list(ledger.AUDIT), list(notify.SENT))\nfor args in (('a','zz',10),('zz','a',10),('a','b',1000),('a','b',0),('a','b',-5)):\n    try:\n        transfer(*args)\n    except Exception: pass\n    assert (accounts.BALANCES, ledger.AUDIT, notify.SENT)==snap, args\nnotify.FAIL[0]=True\ntry:\n    transfer('a','b',10)\nexcept Exception: pass\nassert (accounts.BALANCES, ledger.AUDIT, notify.SENT)==snap\nnotify.FAIL[0]=False\ntransfer('b','a',5)\nassert accounts.BALANCES=={'a':75,'b':25} and len(ledger.AUDIT)==2 and notify.SENT[-1]=='b->a:5'\nprint('ok')\n"},
     "python3 hidden_t.py",
     {"transfer.py": "import accounts, ledger, notify\n\ndef transfer(src, dst, amount):\n    if amount <= 0:\n        raise ValueError('amount must be positive')\n    if src not in accounts.BALANCES or dst not in accounts.BALANCES:\n        raise KeyError('unknown account')\n    before = dict(accounts.BALANCES)\n    try:\n        accounts.debit(src, amount)\n        accounts.credit(dst, amount)\n        notify.send(f'{src}->{dst}:{amount}')\n    except Exception:\n        accounts.BALANCES.clear(); accounts.BALANCES.update(before)\n        raise\n    ledger.AUDIT.append({'from': src, 'to': dst, 'amount': amount, 'balance_from': accounts.BALANCES[src],\n                         'balance_to': accounts.BALANCES[dst]})\n"})

# 4 i18n through cli -> formatter -> messages with plural rules and fallback
task("mf-i18n-plurals", "multi-file",
     "Add language support to the CLI output: report(n_files, n_errors, lang='en') in cli.py must produce the "
     "summary in the requested language using messages.py, with correct plural forms (English: 1 file / 2 files; "
     "French: 0 and 1 use the singular, 2+ the plural; Arabic not supported yet). An unknown language falls back to "
     "English. Keep the current English output byte-for-byte identical.",
     {"messages.py": "MESSAGES = {\n    'en': {'files': ('{n} file', '{n} files'), 'errors': ('{n} error', '{n} errors'), 'summary': 'Checked {files}, found {errors}.'},\n    'fr': {'files': ('{n} fichier', '{n} fichiers'), 'errors': ('{n} erreur', '{n} erreurs'), 'summary': 'Vérifié {files}, trouvé {errors}.'},\n}\n",
      "formatter.py": "def count(n, word):\n    return f'{n} {word}' + ('' if n == 1 else 's')\n",
      "cli.py": "from formatter import count\n\ndef report(n_files, n_errors):\n    return f\"Checked {count(n_files, 'file')}, found {count(n_errors, 'error')}.\"\n"},
     {"hidden_t.py": "from cli import report\nassert report(1,0)=='Checked 1 file, found 0 errors.' and report(2,1)=='Checked 2 files, found 1 error.'\nassert report(0,0)=='Checked 0 files, found 0 errors.'\nassert report(0,1,lang='fr')=='Vérifié 0 fichier, trouvé 1 erreur.', report(0,1,lang='fr')\nassert report(2,5,lang='fr')=='Vérifié 2 fichiers, trouvé 5 erreurs.'\nassert report(1,1,lang='fr')=='Vérifié 1 fichier, trouvé 1 erreur.'\nassert report(3,0,lang='xx')=='Checked 3 files, found 0 errors.'\nassert report(1,2,lang='en')=='Checked 1 file, found 2 errors.'\nprint('ok')\n"},
     "python3 hidden_t.py",
     {"formatter.py": "from messages import MESSAGES\n\ndef plural_index(n, lang):\n    if lang == 'fr':\n        return 0 if n in (0, 1) else 1\n    return 0 if n == 1 else 1\n\ndef count(n, key, lang='en'):\n    return MESSAGES[lang][key][plural_index(n, lang)].format(n=n)\n",
      "cli.py": "from formatter import count\nfrom messages import MESSAGES\n\ndef report(n_files, n_errors, lang='en'):\n    lang = lang if lang in MESSAGES else 'en'\n    return MESSAGES[lang]['summary'].format(files=count(n_files, 'files', lang), errors=count(n_errors, 'errors', lang))\n"})

# 5 rate limiting in a middleware chain
task("mf-rate-limit", "multi-file",
     "Add per-client rate limiting to the HTTP app: at most `limit` requests per client in any rolling `window` "
     "seconds (a sliding window, not fixed buckets). Over the limit the app answers 429 with the same body shape as "
     "other errors and a 'retry_after' field (seconds until the oldest counted request leaves the window, rounded up "
     "to an int). Use the clock passed to create_app so tests can control time. Health checks (/health) are never "
     "limited and never counted.",
     {"http.py": "def error(status, message):\n    return status, {'error': message}\n",
      "middleware.py": "def logging_mw(handler, log):\n    def wrapped(req):\n        resp = handler(req)\n        log.append((req['path'], resp[0]))\n        return resp\n    return wrapped\n",
      "app.py": "import time\nfrom http import error\nfrom middleware import logging_mw\n\ndef router(req):\n    if req['path'] == '/health':\n        return 200, {'ok': True}\n    if req['path'] == '/items':\n        return 200, {'items': [1, 2]}\n    return error(404, 'not found')\n\ndef create_app(limit=5, window=60, clock=time.monotonic, log=None):\n    log = [] if log is None else log\n    return logging_mw(router, log)\n"},
     {"hidden_t.py": "from app import create_app\nnow=[1000.0]\nlog=[]\napp=create_app(limit=3, window=10, clock=lambda: now[0], log=log)\nr=lambda c,p='/items': app({'client':c,'path':p})\nassert [r('a')[0] for _ in range(3)]==[200,200,200]\ns,b=r('a'); assert s==429 and b['error'] and b['retry_after']==10, (s,b)\nassert r('b')[0]==200\nfor _ in range(5): assert r('a','/health')[0]==200\nnow[0]+=4; assert r('a')[0]==429\nnow[0]+=6; assert [r('a')[0] for _ in range(3)]==[200,200,200]\ns,b=r('a'); assert s==429 and b['retry_after']==10, b\nnow[0]+=0.5\ns,b=r('a'); assert b['retry_after']==10, b\nnow[0]+=6\ns,b=r('a'); assert s==429 and b['retry_after']==4, b\nassert r('c','/nope')[0]==404\nassert ('/items',429) in log\nprint('ok')\n"},
     "python3 hidden_t.py",
     {"app.py": "import math, time\nfrom collections import defaultdict, deque\nfrom http import error\nfrom middleware import logging_mw\n\ndef router(req):\n    if req['path'] == '/health':\n        return 200, {'ok': True}\n    if req['path'] == '/items':\n        return 200, {'items': [1, 2]}\n    return error(404, 'not found')\n\ndef rate_limit_mw(handler, limit, window, clock):\n    hits = defaultdict(deque)\n    def wrapped(req):\n        if req['path'] == '/health':\n            return handler(req)\n        now = clock(); q = hits[req.get('client')]\n        while q and q[0] <= now - window:\n            q.popleft()\n        if len(q) >= limit:\n            status, body = error(429, 'rate limited')\n            body['retry_after'] = math.ceil(q[0] + window - now)\n            return status, body\n        q.append(now)\n        return handler(req)\n    return wrapped\n\ndef create_app(limit=5, window=60, clock=time.monotonic, log=None):\n    log = [] if log is None else log\n    return logging_mw(rate_limit_mw(router, limit, window, clock), log)\n"})

# 6 schema validation collecting every error with a path
task("mf-manifest-validation", "multi-file",
     "Plugin manifests are validated one error at a time, with messages that do not say where the problem is. "
     "Change validation so validate(manifest) returns a list of ALL problems as 'path: message' strings (paths like "
     "'name', 'permissions[1]', 'entry.module'), in document order; an empty list means valid. loader.load() must "
     "raise InvalidManifest containing every problem when any exist, and otherwise return the manifest unchanged.",
     {"schema.py": "SCHEMA = {\n    'name': str,\n    'version': str,\n    'permissions': [str],\n    'entry': {'module': str, 'function': str},\n}\n",
      "validate.py": "from schema import SCHEMA\n\ndef validate(m):\n    for key, typ in SCHEMA.items():\n        if key not in m:\n            raise ValueError('missing field')\n        if isinstance(typ, type) and not isinstance(m[key], typ):\n            raise ValueError('bad type')\n    return []\n",
      "loader.py": "import json\nfrom validate import validate\n\nclass InvalidManifest(Exception):\n    pass\n\ndef load(text):\n    m = json.loads(text)\n    try:\n        validate(m)\n    except ValueError as e:\n        raise InvalidManifest(str(e))\n    return m\n"},
     {"hidden_t.py": "import json\nfrom validate import validate\nfrom loader import load, InvalidManifest\ngood={'name':'p','version':'1','permissions':['net','fs'],'entry':{'module':'m','function':'f'}}\nassert validate(good)==[] and load(json.dumps(good))==good\nbad={'version':2,'permissions':['net',3,None],'entry':{'module':'m'}}\nerrs=validate(bad)\nassert len(errs)==5, errs\nassert errs[0].startswith('name:') and errs[1].startswith('version:') and errs[2].startswith('permissions[1]:') and errs[3].startswith('permissions[2]:') and errs[4].startswith('entry.function:'), errs\nassert validate({'name':'p','version':'1','permissions':'net','entry':[]})==[e for e in validate({'name':'p','version':'1','permissions':'net','entry':[]})] and len(validate({'name':'p','version':'1','permissions':'net','entry':[]}))==2\ntry:\n    load(json.dumps(bad)); raise SystemExit('no raise')\nexcept InvalidManifest as e:\n    assert all(x in str(e) for x in errs), str(e)\nprint('ok')\n"},
     "python3 hidden_t.py",
     {"validate.py": "from schema import SCHEMA\n\ndef _check(val, typ, path, out):\n    if isinstance(typ, dict):\n        if not isinstance(val, dict):\n            out.append(f'{path}: expected an object'); return\n        for k, t in typ.items():\n            p = f'{path}.{k}' if path else k\n            if k not in val:\n                out.append(f'{p}: missing')\n            else:\n                _check(val[k], t, p, out)\n    elif isinstance(typ, list):\n        if not isinstance(val, list):\n            out.append(f'{path}: expected a list'); return\n        for i, x in enumerate(val):\n            _check(x, typ[0], f'{path}[{i}]', out)\n    elif not isinstance(val, typ):\n        out.append(f'{path}: expected {typ.__name__}')\n\ndef validate(m):\n    out = []\n    _check(m, SCHEMA, '', out)\n    return out\n",
      "loader.py": "import json\nfrom validate import validate\n\nclass InvalidManifest(Exception):\n    pass\n\ndef load(text):\n    m = json.loads(text)\n    errs = validate(m)\n    if errs:\n        raise InvalidManifest('; '.join(errs))\n    return m\n"})

# 7 JS: units through parse -> scale -> format
task("mf-js-recipe-units", "multi-file",
     "The recipe scaler (src/) ignores units: scaling '2 cups flour' by 3 should give '1.5 quarts flour' style "
     "promotion. Implement unit-aware scaling: volumes in tsp, tbsp, cup, quart (3 tsp = 1 tbsp, 16 tbsp = 1 cup, "
     "4 cup = 1 quart) and weights in g, kg (1000 g = 1 kg). After scaling, express each amount in the largest unit "
     "of its family where the amount is >= 1, rounded to at most 2 decimals with trailing zeros removed. Lines "
     "without a known unit keep scaling as numbers ('2 eggs' x 3 = '6 eggs'). Plural unit spellings (cups, quarts) "
     "are accepted on input; output uses the singular unit name.",
     {"package.json": "{\"name\":\"recipes\",\"type\":\"commonjs\"}\n",
      "src/parse.js": "function parseLine(line) {\n  const m = line.match(/^(\\d+(?:\\.\\d+)?)\\s+(.*)$/)\n  if (!m) return { qty: null, rest: line }\n  return { qty: Number(m[1]), rest: m[2] }\n}\nmodule.exports = { parseLine }\n",
      "src/format.js": "function formatQty(q) {\n  return String(Math.round(q * 100) / 100)\n}\nmodule.exports = { formatQty }\n",
      "src/scale.js": "const { parseLine } = require('./parse')\nconst { formatQty } = require('./format')\nfunction scaleLine(line, factor) {\n  const p = parseLine(line)\n  if (p.qty === null) return line\n  return `${formatQty(p.qty * factor)} ${p.rest}`\n}\nfunction scaleRecipe(lines, factor) { return lines.map(l => scaleLine(l, factor)) }\nmodule.exports = { scaleLine, scaleRecipe }\n"},
     {"hidden_t.js": "const assert=require('assert')\nconst {scaleLine,scaleRecipe}=require('./src/scale')\nassert.strictEqual(scaleLine('2 cups flour',3),'1.5 quart flour')\nassert.strictEqual(scaleLine('1 tbsp salt',2),'2 tbsp salt')\nassert.strictEqual(scaleLine('2 tsp sugar',3),'2 tbsp sugar')\nassert.strictEqual(scaleLine('8 tbsp butter',2),'1 cup butter')\nassert.strictEqual(scaleLine('1 tsp vanilla',0.5),'0.5 tsp vanilla')\nassert.strictEqual(scaleLine('600 g rice',2),'1.2 kg rice')\nassert.strictEqual(scaleLine('250 g cheese',1),'250 g cheese')\nassert.strictEqual(scaleLine('2 eggs',3),'6 eggs')\nassert.strictEqual(scaleLine('salt to taste',2),'salt to taste')\nassert.deepStrictEqual(scaleRecipe(['1 cup milk','3 eggs'],2),['2 cup milk','6 eggs'])\nassert.strictEqual(scaleLine('1 quart stock',0.25),'1 cup stock')\nconsole.log('ok')\n"},
     "node hidden_t.js",
     {"src/scale.js": "const { parseLine } = require('./parse')\nconst { formatQty } = require('./format')\nconst FAM = { volume: [['tsp', 1], ['tbsp', 3], ['cup', 48], ['quart', 192]], weight: [['g', 1], ['kg', 1000]] }\nconst ALIAS = { tsp: 'tsp', tsps: 'tsp', tbsp: 'tbsp', tbsps: 'tbsp', cup: 'cup', cups: 'cup', quart: 'quart', quarts: 'quart', g: 'g', kg: 'kg' }\nfunction find(u) { for (const [f, us] of Object.entries(FAM)) for (const [n, k] of us) if (n === u) return [f, k]; return null }\nfunction scaleLine(line, factor) {\n  const p = parseLine(line)\n  if (p.qty === null) return line\n  const m = p.rest.match(/^(\\S+)\\s*(.*)$/)\n  const unit = m && ALIAS[m[1].toLowerCase()]\n  if (!unit) return `${formatQty(p.qty * factor)} ${p.rest}`\n  const [fam, k] = find(unit)\n  const base = p.qty * k * factor\n  let best = FAM[fam][0]\n  for (const u of FAM[fam]) if (base / u[1] >= 1 - 1e-9) best = u\n  return `${formatQty(base / best[1])} ${best[0]}${m[2] ? ' ' + m[2] : ''}`\n}\nfunction scaleRecipe(lines, factor) { return lines.map(l => scaleLine(l, factor)) }\nmodule.exports = { scaleLine, scaleRecipe }\n"})

# 8 job runner hooks: ordering, context, error isolation
task("mf-job-hooks", "multi-file",
     "Add hooks to the job runner. runner.add_hook(stage, fn) with stage 'before' or 'after'; hooks run in the order "
     "added; each gets a context dict {'job': name, 'attempt': n} and 'after' hooks also get 'result' or 'error'. "
     "A 'before' hook that raises cancels that job (result recorded as status 'cancelled', the job is not run, "
     "'after' hooks still run). An 'after' hook that raises must not affect the job's result; its error is "
     "appended to runner.HOOK_ERRORS as (stage, job, message). Existing retry behaviour stays the same, and hooks "
     "run once per attempt.",
     {"jobs.py": "def ok():\n    return 'done'\n\nFLAKY = {'n': 0}\ndef flaky():\n    FLAKY['n'] += 1\n    if FLAKY['n'] < 2:\n        raise RuntimeError('try again')\n    return 'eventually'\n\ndef broken():\n    raise ValueError('nope')\n",
      "runner.py": "RESULTS = {}\n\ndef run(name, fn, retries=1):\n    for attempt in range(1, retries + 2):\n        try:\n            RESULTS[name] = {'status': 'ok', 'value': fn(), 'attempts': attempt}\n            return RESULTS[name]\n        except Exception as e:\n            last = e\n    RESULTS[name] = {'status': 'failed', 'error': str(last), 'attempts': retries + 1}\n    return RESULTS[name]\n"},
     {"hidden_t.py": "import runner, jobs\nlog=[]\nrunner.add_hook('before', lambda c: log.append(('b1', c['job'], c['attempt'])))\nrunner.add_hook('before', lambda c: log.append(('b2', c['job'], c['attempt'])))\nrunner.add_hook('after', lambda c: log.append(('a', c['job'], c.get('result'), c.get('error'))))\nr=runner.run('ok', jobs.ok); assert r=={'status':'ok','value':'done','attempts':1}\nassert log==[('b1','ok',1),('b2','ok',1),('a','ok','done',None)], log\nlog.clear(); r=runner.run('flaky', jobs.flaky, retries=2)\nassert r['status']=='ok' and r['attempts']==2 and [x[0] for x in log]==['b1','b2','a','b1','b2','a'], log\nassert log[2][3]=='try again'\nlog.clear(); r=runner.run('broken', jobs.broken, retries=0); assert r['status']=='failed' and r['error']=='nope'\ndef boom(c): raise KeyError('hook')\nrunner.add_hook('after', boom)\nr=runner.run('ok2', jobs.ok); assert r['status']=='ok' and runner.HOOK_ERRORS and runner.HOOK_ERRORS[-1][0]=='after' and runner.HOOK_ERRORS[-1][1]=='ok2'\ncalled=[]\ndef veto(c):\n    if c['job']=='vetoed': raise PermissionError('no')\nrunner.add_hook('before', veto)\nr=runner.run('vetoed', lambda: called.append(1))\nassert r['status']=='cancelled' and not called and log[-1][1]=='vetoed', (r, log[-1])\nprint('ok')\n"},
     "python3 hidden_t.py",
     {"runner.py": "RESULTS = {}\nHOOKS = {'before': [], 'after': []}\nHOOK_ERRORS = []\n\ndef add_hook(stage, fn):\n    HOOKS[stage].append(fn)\n\ndef _after(ctx):\n    for h in HOOKS['after']:\n        try:\n            h(dict(ctx))\n        except Exception as e:\n            HOOK_ERRORS.append(('after', ctx['job'], str(e)))\n\ndef run(name, fn, retries=1):\n    for attempt in range(1, retries + 2):\n        ctx = {'job': name, 'attempt': attempt}\n        try:\n            for h in HOOKS['before']:\n                h(dict(ctx))\n        except Exception as e:\n            RESULTS[name] = {'status': 'cancelled', 'error': str(e), 'attempts': attempt}\n            _after(dict(ctx, error=str(e)))\n            return RESULTS[name]\n        try:\n            value = fn()\n        except Exception as e:\n            last = e\n            _after(dict(ctx, error=str(e)))\n            continue\n        RESULTS[name] = {'status': 'ok', 'value': value, 'attempts': attempt}\n        _after(dict(ctx, result=value))\n        return RESULTS[name]\n    RESULTS[name] = {'status': 'failed', 'error': str(last), 'attempts': retries + 1}\n    return RESULTS[name]\n"})

# 9 dependency-aware module rename across a package
task("mf-rename-module", "multi-file",
     "Rename the package module geo/calc.py to geo/distance.py and the function dist() in it to haversine_km(). "
     "Update every import and call site in the project. For backwards compatibility geo.calc must still import and "
     "geo.calc.dist must still work but emit a DeprecationWarning when called. The CLI output must not change.",
     {"geo/__init__.py": "from .calc import dist\n",
      "geo/calc.py": "import math\n\ndef dist(a, b):\n    lat1, lon1 = map(math.radians, a)\n    lat2, lon2 = map(math.radians, b)\n    h = math.sin((lat2 - lat1) / 2) ** 2 + math.cos(lat1) * math.cos(lat2) * math.sin((lon2 - lon1) / 2) ** 2\n    return 2 * 6371.0 * math.asin(math.sqrt(h))\n",
      "geo/routes.py": "from geo.calc import dist\n\ndef total(points):\n    return sum(dist(points[i], points[i + 1]) for i in range(len(points) - 1))\n",
      "stores.py": "import geo\n\ndef nearest(here, stores):\n    return min(stores, key=lambda s: geo.dist(here, s[1]))[0]\n",
      "cli.py": "from geo.routes import total\nfrom stores import nearest\n\nif __name__ == '__main__':\n    pts = [(51.5, -0.12), (48.85, 2.35), (52.52, 13.4)]\n    print(round(total(pts), 1))\n    print(nearest((50.0, 8.0), [('paris', (48.85, 2.35)), ('berlin', (52.52, 13.4))]))\n"},
     {"hidden_t.sh": "set -e\ntest \"$(python3 cli.py)\" = \"$(printf '1220.8\\nparis')\" || { python3 cli.py; exit 1; }\ntest -f geo/distance.py\n! grep -rn 'def dist(' --include=*.py geo/distance.py\nn=$(grep -rln 'geo.calc\\|from .calc\\|\\bdist(' --include=*.py . | grep -v 'geo/calc.py' | grep -v hidden_ | wc -l | tr -d ' '); test \"$n\" = 0 || { grep -rn 'geo.calc\\|from .calc\\|\\bdist(' --include=*.py . | grep -v geo/calc.py; exit 1; }\npython3 -W error::DeprecationWarning -c 'import geo.distance as d; assert abs(d.haversine_km((0,0),(0,1))-111.19)<0.01'\npython3 -c \"\nimport warnings\nwith warnings.catch_warnings(record=True) as w:\n    warnings.simplefilter('always')\n    import geo.calc\n    v=geo.calc.dist((0,0),(0,1))\nassert abs(v-111.19)<0.01 and any(issubclass(x.category, DeprecationWarning) for x in w)\n\"\necho ok\n"},
     "bash hidden_t.sh",
     {"geo/__init__.py": "from .distance import haversine_km\n",
      "geo/distance.py": "import math\n\ndef haversine_km(a, b):\n    lat1, lon1 = map(math.radians, a)\n    lat2, lon2 = map(math.radians, b)\n    h = math.sin((lat2 - lat1) / 2) ** 2 + math.cos(lat1) * math.cos(lat2) * math.sin((lon2 - lon1) / 2) ** 2\n    return 2 * 6371.0 * math.asin(math.sqrt(h))\n",
      "geo/calc.py": "import warnings\nfrom .distance import haversine_km\n\ndef dist(a, b):\n    warnings.warn('geo.calc.dist is deprecated; use geo.distance.haversine_km', DeprecationWarning, stacklevel=2)\n    return haversine_km(a, b)\n",
      "geo/routes.py": "from geo.distance import haversine_km\n\ndef total(points):\n    return sum(haversine_km(points[i], points[i + 1]) for i in range(len(points) - 1))\n",
      "stores.py": "import geo\n\ndef nearest(here, stores):\n    return min(stores, key=lambda s: geo.haversine_km(here, s[1]))[0]\n"})
